curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "types=public_channel" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(f\"Channel: {ch['name']} (id: {ch['id']})\")
else:
    print(f\"Error: {data}\")
"

curl -s -X POST https://slack.com/api/conversations.replies -H "Authorization: Bearer <TOKEN>" -d "channel=C_INC" -d "ts=1789999560.000001" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for msg in data['messages']:
        print(f\"ts: {msg['ts']}, user: {msg['user']}, text: {msg['text'][:120]}\")
else:
    print(f\"Error: {data}\")
"

curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" -d "channel=C_INC" -d "limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for msg in data['messages']:
        print(f\"ts: {msg['ts']}, user: {msg['user']}, thread_ts: {msg.get('thread_ts','N/A')}, text: {msg['text'][:120]}\")
else:
    print(f\"Error: {data}\")
"
